387	/// Read a workflow file from disk and parse it into a [`WorkflowFile`].
388	///
389	/// This is the public entry point used by `bivvy lint --workflow <name>`
390	/// and discovery-based commands that want a single workflow file in
391	/// isolation, without merging anything else.
392	pub fn load_single_workflow_file(path: &Path) -> Result<WorkflowFile> {
393	    let value = load_config_value(path)?;
394	    parse_workflow_file_value(value, path)
395	}
