402	        if e.kind() == std::io::ErrorKind::NotFound {
403	            BivvyError::ConfigNotFound {
404	                path: path.to_path_buf(),
405	            }
406	        } else {
407	            BivvyError::Io(e)
408	        }
409	    })?;
410	    serde_yaml::from_str(&content).map_err(|e| BivvyError::ConfigParseError {
411	        path: path.to_path_buf(),
412	        message: e.to_string(),
413	    })
