use crate::config::{load_config_file, load_merged_config, ConfigPaths};
use crate::error::{BivvyError, Result};
use crate::ui::{OutputMode, UserInterface};

use super::dispatcher::{Command, CommandResult};

/// The config command implementation.
pub struct ConfigCommand {
    project_root: PathBuf,
    args: ConfigArgs,
    config_override: Option<PathBuf>,
}

impl ConfigCommand {
    /// Create a new config command.
    pub fn new(project_root: &Path, args: ConfigArgs) -> Self {
        Self {
            project_root: project_root.to_path_buf(),
            args,
            config_override: None,
        }
    }

    /// Set an override config path.
    pub fn with_config_override(mut self, config_override: Option<PathBuf>) -> Self {
        self.config_override = config_override;
        self
    }

    /// Get the project root path.
    pub fn project_root(&self) -> &Path {
        &self.project_root
    }

    /// Get the command arguments.
    pub fn args(&self) -> &ConfigArgs {
        &self.args
    }
}

impl Command for ConfigCommand {
    fn execute(&self, ui: &mut dyn UserInterface) -> Result<CommandResult> {
        let paths = ConfigPaths::discover(&self.project_root);

        // Load configuration: override path, merged (all sources), or project-only
        let config = if let Some(ref override_path) = self.config_override {
            load_config_file(override_path)?
        } else if self.args.merged {
            match load_merged_config(&self.project_root) {
                Ok(c) => c,
                Err(BivvyError::ConfigNotFound { .. }) => {
                    ui.error("No configuration found. Run 'bivvy init' first.");
                    return Ok(CommandResult::failure(2));
                }
                Err(e) => return Err(e),
            }
        } else {
            // Load only the project config (.bivvy/config.yml) without merging
            match &paths.project {
                Some(project_path) => load_config_file(project_path)?,
                None => {
                    ui.error("No configuration found. Run 'bivvy init' first.");
                    return Ok(CommandResult::failure(2));
                }
            }
        };

        // Apply config default_output when no CLI flag was explicitly set
        if ui.output_mode() == OutputMode::Normal {
            ui.set_output_mode(config.settings.defaults.output.into());
        }

        // Show config file path(s)
        if self.args.merged {
            let existing: Vec<_> = paths.all_existing();
            if !existing.is_empty() {
                for path in &existing {
                    ui.message(&format!("# {}", path.display()));
                }
                ui.message("");
            }
        } else if let Some(project_path) = &paths.project {
            ui.message(&format!("# {}", project_path.display()));
            ui.message("");
        }

        // Output format
        if self.args.json {
            let json =
                serde_json::to_string_pretty(&config).map_err(|e| BivvyError::Other(e.into()))?;
            ui.message(&json);
        } else {
            // --yaml or default: output as YAML
            let yaml = serde_yaml::to_string(&config).map_err(|e| BivvyError::Other(e.into()))?;
            ui.message(&yaml);
        }

        Ok(CommandResult::success())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::ui::{MockUI, UiState};
    use std::fs;
    use tempfile::TempDir;

    fn setup_project(config: &str) -> TempDir {
        let temp = TempDir::new().unwrap();
        let bivvy_dir = temp.path().join(".bivvy");
        fs::create_dir_all(&bivvy_dir).unwrap();
        fs::write(bivvy_dir.join("config.yml"), config).unwrap();
        temp
    }

    #[test]
    fn config_command_creation() {
        let temp = TempDir::new().unwrap();
        let args = ConfigArgs::default();
        let cmd = ConfigCommand::new(temp.path(), args);

        assert_eq!(cmd.project_root(), temp.path());
    }

    #[test]
    fn config_no_config() {
        let temp = TempDir::new().unwrap();
        let args = ConfigArgs::default();
        let cmd = ConfigCommand::new(temp.path(), args);
        let mut ui = MockUI::new();

        let result = cmd.execute(&mut ui).unwrap();

        assert!(!result.success);
        assert_eq!(result.exit_code, 2);
    }

    #[test]
    fn config_shows_config_path() {
        let config = r#"
app_name: Test
steps:
  hello:
    command: echo hello
workflows:
  default:
    steps: [hello]
"#;
        let temp = setup_project(config);
        let args = ConfigArgs::default();
        let cmd = ConfigCommand::new(temp.path(), args);
        let mut ui = MockUI::new();

        cmd.execute(&mut ui).unwrap();

        assert!(ui.messages().iter().any(|m| m.contains("config.yml")));
    }

    #[test]
    fn config_applies_config_default_output() {
        let config = r#"
app_name: Test
settings:
  defaults:
    output: quiet
steps:
  hello:
    command: echo hello
workflows:
  default:
    steps: [hello]
"#;
        let temp = setup_project(config);
        let args = ConfigArgs::default();
        let cmd = ConfigCommand::new(temp.path(), args);
        let mut ui = MockUI::new();

        cmd.execute(&mut ui).unwrap();

        assert_eq!(ui.output_mode(), crate::ui::OutputMode::Quiet);
    }

    #[test]
    fn config_yaml_output() {
        let config = r#"
app_name: Test
steps:
  hello:
    command: echo hello
workflows:
  default:
    steps: [hello]
"#;
        let temp = setup_project(config);
        let args = ConfigArgs::default();
        let cmd = ConfigCommand::new(temp.path(), args);
        let mut ui = MockUI::new();

        let result = cmd.execute(&mut ui).unwrap();

        assert!(result.success);
    }

    #[test]
    fn config_json_output() {
        let config = r#"
app_name: Test
steps:
  hello:
    command: echo hello
workflows:
  default:
    steps: [hello]
"#;
        let temp = setup_project(config);
        let args = ConfigArgs {
            json: true,
            ..Default::default()
        };
        let cmd = ConfigCommand::new(temp.path(), args);
        let mut ui = MockUI::new();

        let result = cmd.execute(&mut ui).unwrap();

        assert!(result.success);
    }
}

//! Configuration schema definitions for Bivvy.
//!
//! This module contains all the struct definitions that map to
//! the YAML configuration file format.

use crate::checks::{Check, SatisfactionCondition};
use schemars::JsonSchema;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::path::PathBuf;

/// Helper for `serde_yaml::Value` fields — accepts any valid YAML/JSON value.
fn any_value_schema(_: &mut schemars::generate::SchemaGenerator) -> schemars::Schema {
    true.into()
}

/// Helper for `HashMap<String, serde_yaml::Value>` — object with any values.
fn any_value_map_schema(_: &mut schemars::generate::SchemaGenerator) -> schemars::Schema {
    let mut map = serde_json::Map::new();
    map.insert(
        "type".to_string(),
        serde_json::Value::String("object".to_string()),
    );
    map.insert(
        "additionalProperties".to_string(),
        serde_json::Value::Bool(true),
    );
    map.into()
}

/// Root configuration structure for bivvy.yml
#[derive(Debug, Clone, Default, Serialize, Deserialize, JsonSchema)]
#[serde(default, deny_unknown_fields)]
pub struct BivvyConfig {
    /// Application name (for display purposes)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub app_name: Option<String>,

    /// Global settings
    pub settings: Settings,

    /// Remote template sources
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub template_sources: Vec<TemplateSource>,

    /// Step definitions
    #[serde(default)]
    pub steps: HashMap<String, StepConfig>,

    /// Workflow definitions
    #[serde(default)]
    pub workflows: HashMap<String, WorkflowConfig>,

    /// Secrets configuration
    #[serde(default, skip_serializing_if = "HashMap::is_empty")]
    pub secrets: HashMap<String, SecretConfig>,

    /// Config inheritance
    #[serde(skip_serializing_if = "Option::is_none")]
    pub extends: Option<Vec<ExtendsConfig>>,

    /// Custom requirement definitions
    #[serde(default, skip_serializing_if = "HashMap::is_empty")]
    pub requirements: HashMap<String, CustomRequirement>,

    /// User-defined variables for interpolation.
    #[serde(default, skip_serializing_if = "HashMap::is_empty")]
    pub vars: HashMap<String, VarDefinition>,
}

/// JSONL event logging settings.
///
/// Controls whether structured event logs are written to `~/.bivvy/logs/`
/// and how long they are retained.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
#[serde(default)]
pub struct LoggingSettings {
    /// Enable JSONL event logging. When false, no log files are written.
    #[serde(default = "default_true", skip_serializing_if = "is_true")]
    pub logging: bool,

    /// Maximum age of log files in days. Files older than this are deleted
    /// during cleanup. Default: 30.
    #[serde(
        default = "default_log_retention_days",
        skip_serializing_if = "is_default_log_retention_days"
    )]
    pub log_retention_days: u32,

    /// Maximum total size of log files in megabytes. When exceeded, oldest
    /// files are deleted first. Default: 500.
    #[serde(
        default = "default_log_retention_mb",
        skip_serializing_if = "is_default_log_retention_mb"
    )]
    pub log_retention_mb: u64,
}

impl Default for LoggingSettings {
    fn default() -> Self {
        Self {
            logging: true,
            log_retention_days: default_log_retention_days(),
            log_retention_mb: default_log_retention_mb(),
        }
    }
}

impl LoggingSettings {
    /// Convert to a [`RetentionPolicy`](crate::logging::RetentionPolicy).
    pub fn to_retention_policy(&self) -> crate::logging::RetentionPolicy {
        crate::logging::RetentionPolicy {
            max_age_days: self.log_retention_days,
            max_size_mb: self.log_retention_mb,
        }
    }
}

fn default_log_retention_days() -> u32 {
    30
}

fn is_default_log_retention_days(v: &u32) -> bool {
    *v == default_log_retention_days()
}

fn default_log_retention_mb() -> u64 {
    500
}

fn is_default_log_retention_mb(v: &u64) -> bool {
    *v == default_log_retention_mb()
}

/// Execution-related settings (parallelism, history, updates).
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
#[serde(default)]
pub struct ExecutionSettings {
    /// Enable parallel execution
    #[serde(default, skip_serializing_if = "is_false")]
    pub parallel: bool,

    /// Maximum concurrent steps
    #[serde(
        default = "default_max_parallel",
        skip_serializing_if = "is_default_max_parallel"
    )]
    pub max_parallel: usize,

    /// History retention count

