1	//! Status command implementation.
2	//!
3	//! The `bivvy status` command shows current setup status.
4	
5	use std::collections::HashSet;
6	use std::path::{Path, PathBuf};
7	use std::time::Duration;
8	
9	use serde_json::json;
10	
11	use crate::cli::args::StatusArgs;
12	use crate::config::{load_config, load_for_run, load_project_config};
13	use crate::environment::resolver::ResolvedEnvironment;
14	use crate::error::{BivvyError, Result};
15	use crate::requirements::checker::GapChecker;
16	use crate::requirements::probe::EnvironmentProbe;
17	use crate::requirements::registry::RequirementRegistry;
18	use crate::requirements::status::RequirementStatus;
19	use crate::state::{ProjectId, StateStore, StepStatus};
20	use crate::ui::theme::BivvyTheme;
21	use crate::ui::{format_relative_time, hints, OutputMode, StatusKind, UserInterface};
22	
23	use super::dispatcher::{Command, CommandResult};
24	
25	/// The status command implementation.
26	pub struct StatusCommand {
27	    project_root: PathBuf,
28	    args: StatusArgs,
29	    config_override: Option<PathBuf>,
30	}
31	
32	impl StatusCommand {
33	    /// Create a new status command.
34	    pub fn new(project_root: &Path, args: StatusArgs) -> Self {
35	        Self {
36	            project_root: project_root.to_path_buf(),
37	            args,
38	            config_override: None,
39	        }
40	    }
41	
42	    /// Set an override config path.
43	    pub fn with_config_override(mut self, config_override: Option<PathBuf>) -> Self {
44	        self.config_override = config_override;
45	        self
46	    }
47	
48	    /// Get the project root path.
49	    pub fn project_root(&self) -> &Path {
50	        &self.project_root
51	    }
52	
53	    /// Get the command arguments.
54	    pub fn args(&self) -> &StatusArgs {
55	        &self.args
56	    }
57	
58	    /// Resolve the target environment using the priority chain.
59	    fn resolve_environment(&self, config: &crate::config::BivvyConfig) -> ResolvedEnvironment {
60	        ResolvedEnvironment::resolve_from_config(self.args.env.as_deref(), &config.settings)
61	    }
62	}
63	
64	impl StatusCommand {
65	    /// Produce JSON output for the status command.
66	    fn execute_json(
67	        &self,
68	        ui: &mut dyn UserInterface,
69	        config: &crate::config::BivvyConfig,
70	        state: &StateStore,
71	        resolved_env: &ResolvedEnvironment,
72	    ) -> Result<CommandResult> {
73	        let app_name = config.app_name.as_deref().unwrap_or("Bivvy Setup");
74	
75	        // Build step statuses
76	        let step_names: Vec<&String> = if let Some(ref step_name) = self.args.step {
77	            if config.steps.contains_key(step_name) {
78	                vec![step_name]
79	            } else {
80	                let err = json!({ "error": format!("Unknown step: {}", step_name) });
81	                ui.message(
82	                    &serde_json::to_string_pretty(&err)
83	                        .map_err(|e| anyhow::anyhow!("JSON serialization failed: {e}"))?,
84	                );
85	                return Ok(CommandResult::failure(1));
86	            }
87	        } else {
88	            config.steps.keys().collect()
89	        };
90	
91	        let steps: Vec<serde_json::Value> = step_names
92	            .iter()
93	            .map(|name| {
94	                let step_config = config.steps.get(*name);
95	                let skipped = step_config
96	                    .map(|s| {
97	                        !s.scoping.only_environments.is_empty()
98	                            && !s
99	                                .scoping
100	                                .only_environments
101	                                .iter()
102	                                .any(|e| e == &resolved_env.name)
103	                    })
104	                    .unwrap_or(false);
105	
106	                if skipped {
107	                    return json!({
108	                        "name": name,
109	                        "status": "skipped",
110	                        "reason": format!("skipped in {}", resolved_env.name),
111	                    });
112	                }
113	
114	                let step_state = state.get_step(name);
115	                let status = step_state.map(|s| s.status).unwrap_or(StepStatus::NeverRun);
116	                let status_str = match status {
117	                    StepStatus::Success => "success",
118	                    StepStatus::Failed => "failed",
119	                    StepStatus::Skipped => "skipped",
120	                    StepStatus::NeverRun => "pending",
121	                };
122	
123	                let mut obj = json!({
124	                    "name": name,
125	                    "status": status_str,
126	                });
127	
128	                if let Some(ss) = step_state {
129	                    if let Some(ts) = ss.last_run {
130	                        obj["last_run"] = json!(ts.to_rfc3339());
131	                    }
132	                    if let Some(ms) = ss.duration_ms {
133	                        obj["duration_ms"] = json!(ms);
134	                    }
135	                }
136	
137	                obj
138	            })
139	            .collect();
140	
141	        // Build requirements
142	        let all_reqs: HashSet<String> = config
143	            .steps
144	            .values()
145	            .flat_map(|s| s.requires.iter().cloned())
146	            .collect();
147	
148	        let requirements: Vec<serde_json::Value> = if !all_reqs.is_empty() {
149	            let probe = EnvironmentProbe::run();
150	            let req_registry = RequirementRegistry::new().with_custom(&config.requirements);
151	            let mut gap_checker = GapChecker::new(&req_registry, &probe, &self.project_root);
152	
153	            let mut sorted_reqs: Vec<&str> = all_reqs.iter().map(|s| s.as_str()).collect();
154	            sorted_reqs.sort();
155	
156	            sorted_reqs
157	                .iter()
158	                .map(|req_name| {
159	                    let status = gap_checker.check_one(req_name);
160	                    let (status_str, detail) = json_requirement_status(&status);
161	                    let mut obj = json!({
162	                        "name": req_name,
163	                        "status": status_str,
164	                    });
165	                    if let Some(d) = detail {
166	                        obj["detail"] = json!(d);
167	                    }
168	                    obj
169	                })
170	                .collect()
171	        } else {
172	            Vec::new()
173	        };
174	
175	        // Assemble top-level JSON
176	        let mut output = json!({
177	            "app_name": app_name,
178	            "environment": {
179	                "name": resolved_env.name,
180	                "source": resolved_env.source.to_string(),
181	            },
182	            "steps": steps,
183	        });
184	
185	        if !requirements.is_empty() {
186	            output["requirements"] = json!(requirements);
187	        }
188	
189	        let json_str = serde_json::to_string_pretty(&output)
190	            .map_err(|e| anyhow::anyhow!("JSON serialization failed: {e}"))?;
191	        ui.message(&json_str);
192	
193	        Ok(CommandResult::success())
194	    }
195	}
196	
197	impl Command for StatusCommand {
198	    fn execute(&self, ui: &mut dyn UserInterface) -> Result<CommandResult> {
199	        // Create event bus for structured logging
200	        let mut event_bus = crate::logging::EventBus::new();
201	        if let Ok(logger) = crate::logging::EventLogger::new(
202	            crate::logging::default_log_dir(),
203	            &format!("sess_{}_status", chrono::Utc::now().format("%Y%m%d%H%M%S"),),
204	            crate::logging::RetentionPolicy::default(),
205	        ) {
206	            event_bus.add_consumer(Box::new(logger));
207	        }
208	        let start = std::time::Instant::now();
209	
210	        event_bus.emit(&crate::logging::BivvyEvent::SessionStarted {
211	            command: "status".to_string(),
212	            args: vec![],
213	            version: env!("CARGO_PKG_VERSION").to_string(),
214	            os: Some(std::env::consts::OS.to_string()),
215	            working_directory: Some(self.project_root.display().to_string()),
216	        });
217	
218	        // Load configuration. With an explicit workflow, we use the
219	        // run-style loader so workflow-bundled steps are visible. Otherwise
220	        // the cheap project-only loader is enough for a status overview.
221	        let config = if let Some(ref override_path) = self.config_override {
222	            match load_config(&self.project_root, Some(override_path)) {
223	                Ok(c) => c,
224	                Err(BivvyError::ConfigNotFound { .. }) => {
225	                    ui.error("No configuration found. Run 'bivvy init' first.");
226	                    event_bus.emit(&crate::logging::BivvyEvent::SessionEnded {
227	                        exit_code: 2,
228	                        duration_ms: start.elapsed().as_millis() as u64,
229	                    });
