47	/// Check whether a var name is a valid identifier.
48	///
49	/// Valid names start with a letter or underscore and contain only
50	/// ASCII letters, digits, and underscores.
51	fn is_valid_var_name(name: &str) -> bool {
52	    if name.is_empty() {
53	        return false;
54	    }
55	    let mut chars = name.chars();
56	    let first = chars.next().unwrap();
57	    if !first.is_ascii_alphabetic() && first != '_' {
58	        return false;
59	    }
60	    chars.all(|c| c.is_ascii_alphanumeric() || c == '_')
61	}
62	
63	/// Validate user-defined variable declarations.
64	fn validate_vars(config: &BivvyConfig) -> Vec<ValidationError> {
65	    let mut errors = Vec::new();
66	
67	    for (name, def) in &config.vars {
68	        // Empty or invalid var name
69	        if !is_valid_var_name(name) {
70	            errors.push(ValidationError {
71	                rule: "invalid-var-name".to_string(),
72	                message: format!(
73	                    "Variable '{}' has an invalid name. \
74	                     Names must start with a letter or underscore and \
75	                     contain only letters, digits, and underscores.",
76	                    name
77	                ),
78	                step: None,
79	                workflow: None,
80	            });
81	        }
82	
83	        // Collision with builtin variables
84	        if BUILTIN_VAR_NAMES.contains(&name.as_str()) {
85	            errors.push(ValidationError {
86	                rule: "builtin-var-collision".to_string(),
87	                message: format!(
88	                    "Variable '{}' collides with a built-in variable. \
89	                     Choose a different name.",
90	                    name
91	                ),
92	                step: None,
93	                workflow: None,
94	            });
95	        }
96	
97	        // Computed vars must have a non-empty command
98	        if let VarDefinition::Computed { command } = def {
99	            if command.trim().is_empty() {
