    }

    #[test]
    fn load_merged_config_errors_on_non_mapping_config_file() {
        // If a config file contains valid YAML that isn't a mapping
        // (e.g., a bare string or array), it should error — not silently
        // produce defaults.
        let temp = TempDir::new().unwrap();
        let bivvy_dir = temp.path().join(".bivvy");
        fs::create_dir_all(&bivvy_dir).unwrap();

        // Config file is a YAML string, not a mapping
        fs::write(bivvy_dir.join("config.yml"), "\"just a string\"").unwrap();

        let result = load_merged_config(temp.path());
        assert!(result.is_err());
        let err = result.unwrap_err();
        assert!(
            matches!(err, BivvyError::ConfigParseError { .. }),
            "Expected ConfigParseError, got: {:?}",
            err
        );
    }

    #[test]
    fn load_merged_config_errors_on_non_mapping_local_override() {
        // Non-mapping values in local overrides should error, not silently
        // replace the config with defaults.
        let temp = TempDir::new().unwrap();
        let bivvy_dir = temp.path().join(".bivvy");
        fs::create_dir_all(&bivvy_dir).unwrap();

        fs::write(bivvy_dir.join("config.yml"), "app_name: MyApp").unwrap();

        // Local override is a YAML array
        fs::write(bivvy_dir.join("config.local.yml"), "- item1\n- item2\n").unwrap();

        let result = load_merged_config(temp.path());
        assert!(result.is_err());
        let err = result.unwrap_err();
        assert!(
            matches!(err, BivvyError::ConfigParseError { .. }),
            "Expected ConfigParseError, got: {:?}",
            err
        );
    }
